"""Domain representation of a YouTube album manifest.

This module contains the domain representation of the information
provided by the user for an album.

The manifest is independent of the format used to provide it.
YAML parsing belongs to the infrastructure layer.
"""

from __future__ import annotations

from pathlib import Path

from domain.youtube.publication_settings import PublicationSettings


class AlbumManifest:
    """Represents the desired configuration of a YouTube album."""

    def __init__(
        self,
        name: str,
        name_prefix: str,
        videos: list[str],
        description: str,
        thumbnail: Path | None,
        playlists: list[str],
        made_for_kids: bool,
        contains_synthetic_media: bool,
        tags: list[str] | None,
        game: str,
        publication: PublicationSettings,
    ) -> None:
        if len(description) > 5000:
            raise ValueError(
                "Album manifest description must not exceed 5000 characters."
            )

        if not isinstance(publication, PublicationSettings):
            raise TypeError(
                "publication must be a PublicationSettings instance."
            )

        self._name = name
        self._name_prefix = name_prefix
        self._videos = list(videos)
        self._description = description
        self._thumbnail = thumbnail
        self._playlists = list(playlists)
        self._made_for_kids = made_for_kids
        self._contains_synthetic_media = contains_synthetic_media
        self._tags = list(tags) if tags is not None else None
        self._game = game
        self._publication = publication

    @property
    def name(self) -> str:
        """Return the album name."""
        return self._name

    @property
    def name_prefix(self) -> str:
        """Return the prefix used to compose video names."""
        return self._name_prefix

    @property
    def videos(self) -> tuple[str, ...]:
        """Return the desired video specifications."""
        return tuple(self._videos)

    @property
    def description(self) -> str:
        """Return the desired album description."""
        return self._description

    @property
    def thumbnail(self) -> Path | None:
        """Return the album thumbnail path."""
        return self._thumbnail

    @property
    def playlists(self) -> tuple[str, ...]:
        """Return the YouTube playlist IDs."""
        return tuple(self._playlists)

    @property
    def made_for_kids(self) -> bool:
        """Return whether the videos are made for kids."""
        return self._made_for_kids

    @property
    def contains_synthetic_media(self) -> bool:
        """Return whether the videos contain synthetic media."""
        return self._contains_synthetic_media

    @property
    def tags(self) -> tuple[str, ...] | None:
        """Return the desired video tags."""
        return tuple(self._tags) if self._tags is not None else None

    @property
    def game(self) -> str:
        """Return the game associated with the album."""
        return self._game

    @property
    def publication(self) -> PublicationSettings:
        return self._publication

    def __repr__(self) -> str:
        return (
            f"AlbumManifest("
            f"name={self._name!r}, "
            f"video_count={len(self._videos)})"
        )

from __future__ import annotations

from datetime import datetime


class PublicationSettings:
    def __init__(
        self,
        first_publish_at: datetime,
        interval_days: int,
    ) -> None:
        if not isinstance(first_publish_at, datetime):
            raise TypeError("first_publish_at must be a datetime.")

        if isinstance(interval_days, bool) or not isinstance(interval_days, int):
            raise TypeError("interval_days must be an integer.")

        if interval_days <= 0:
            raise ValueError("interval_days must be greater than zero.")

        self._first_publish_at = first_publish_at
        self._interval_days = interval_days

    @property
    def first_publish_at(self) -> datetime:
        return self._first_publish_at

    @property
    def interval_days(self) -> int:
        return self._interval_days

    def __repr__(self) -> str:
        return (
            "PublicationSettings("
            f"first_publish_at={self._first_publish_at!r}, "
            f"interval_days={self._interval_days!r}"
            ")"
        )

"""Domain validation types for the YouTube album workflow.

This module contains domain-level validation results and errors.
It does not perform infrastructure operations or modify remote state.
"""

from __future__ import annotations

from dataclasses import dataclass


@dataclass(frozen=True)
class ValidationError:
    """Represents a single domain validation error."""

    field: str
    message: str


class ValidationResult:
    """Represents the result of validating a domain object."""

    def __init__(self, errors: list[ValidationError] | None = None) -> None:
        self._errors = list(errors) if errors is not None else []

    @property
    def is_valid(self) -> bool:
        """Return whether the validation completed without errors."""
        return not self._errors

    @property
    def errors(self) -> tuple[ValidationError, ...]:
        """Return the validation errors."""
        return tuple(self._errors)

    def add_error(self, field: str, message: str) -> None:
        """Add a validation error to the result."""
        self._errors.append(
            ValidationError(
                field=field,
                message=message,
            )
        )

from __future__ import annotations

from dataclasses import dataclass
from enum import Enum


class PrivacyStatus(str, Enum):
    """YouTube video privacy status."""

    PRIVATE = "private"
    PUBLIC = "public"
    UNLISTED = "unlisted"


@dataclass(frozen=True)
class YouTubeVideo:
    """Represents a video discovered on YouTube."""

    video_id: str
    title: str
    description: str | None
    privacy_status: PrivacyStatus

    def __post_init__(self) -> None:
        if not isinstance(self.video_id, str) or not self.video_id.strip():
            raise ValueError("video_id must be a non-empty string.")

        if not isinstance(self.title, str) or not self.title.strip():
            raise ValueError("title must be a non-empty string.")

