from __future__ import annotations

import re
from datetime import timedelta, datetime
from typing import Iterable

from domain.youtube.album import Album
from domain.youtube.album_manifest import AlbumManifest
from domain.youtube.video import Video, VideoType
from domain.youtube.video_metadata import VideoMetadata
from domain.youtube.youtube_video import YouTubeVideo


class AlbumBuildError(RuntimeError):
    """Raised when an Album cannot be built from the manifest and YouTube videos."""


class AlbumBuilder:
    """
    Builds an Album by combining the album manifest with discovered YouTube videos.

    The manifest defines the desired album configuration, while YouTubeDiscovery
    provides the YouTube-specific information required to identify each video.

    The resulting Album contains the complete desired configuration and can be
    passed to the planning phase.
    """

    _SONG_TITLE_PATTERN = re.compile(r"^(\d+)\s+(.+)$")

    def build(
        self,
        manifest: AlbumManifest,
        youtube_videos: tuple[YouTubeVideo, ...],
    ) -> Album:
        """
        Build an Album from an album manifest and discovered YouTube videos.

        YouTube videos may be returned in reverse upload order. Their logical
        position is determined by the numeric prefix in their titles.

        Raises:
            AlbumBuildError: If the manifest and YouTube videos cannot be matched.
        """
        if not youtube_videos:
            raise AlbumBuildError(
                "No private YouTube videos were discovered."
            )

        manifest_songs, manifest_compilation = self._parse_manifest(manifest)

        youtube_songs, youtube_compilation = self._parse_youtube_videos(
            youtube_videos
        )

        missing, extra = self._find_mismatches(
            manifest_songs=manifest_songs,
            manifest_compilation=manifest_compilation,
            youtube_songs=youtube_songs,
            youtube_compilation=youtube_compilation,
        )

        if missing or extra:
            raise AlbumBuildError(
                self._format_mismatch_error(
                    missing=missing,
                    extra=extra,
                )
            )

        videos = self._build_videos(
            manifest=manifest,
            manifest_songs=manifest_songs,
            youtube_songs=youtube_songs,
            youtube_compilation=youtube_compilation,
        )

        return Album(
            name=manifest.name,
            description=manifest.description,
            playlists=list(manifest.playlists),
            game=manifest.game,
            publication=manifest.publication,
            tags=list(manifest.tags) if manifest.tags is not None else None,
            thumbnail=manifest.thumbnail,
            videos=videos,
        )

    def _parse_manifest(
        self,
        manifest: AlbumManifest,
    ) -> tuple[dict[int, str], str]:
        songs: dict[int, str] = {}
        compilation: str | None = None

        for title in manifest.videos:
            match = self._SONG_TITLE_PATTERN.match(title)

            if match is None:
                if compilation is not None:
                    raise AlbumBuildError(
                        "Manifest contains more than one compilation."
                    )

                compilation = title
                continue

            position = int(match.group(1))

            if position in songs:
                raise AlbumBuildError(
                    f"Manifest contains duplicate song position {position}."
                )

            songs[position] = title

        if compilation is None:
            raise AlbumBuildError(
                "Manifest does not contain a compilation."
            )

        return songs, compilation

    def _parse_youtube_videos(
        self,
        youtube_videos: Iterable[YouTubeVideo],
    ) -> tuple[dict[int, YouTubeVideo], YouTubeVideo | None]:
        songs: dict[int, YouTubeVideo] = {}
        compilation: YouTubeVideo | None = None

        for video in youtube_videos:
            match = self._SONG_TITLE_PATTERN.match(video.title)

            if match is None:
                if compilation is not None:
                    raise AlbumBuildError(
                        "YouTube discovery contains more than one compilation."
                    )

                compilation = video
                continue

            position = int(match.group(1))

            if position in songs:
                raise AlbumBuildError(
                    "YouTube discovery contains duplicate song position "
                    f"{position}."
                )

            songs[position] = video

        return songs, compilation


    @staticmethod
    def _find_mismatches(
        manifest_songs: dict[int, str],
        manifest_compilation: str,
        youtube_songs: dict[int, YouTubeVideo],
        youtube_compilation: YouTubeVideo | None,
    ) -> tuple[list[str], list[str]]:
        missing: list[str] = []
        extra: list[str] = []

        manifest_positions = set(manifest_songs)
        youtube_positions = set(youtube_songs)

        for position in sorted(manifest_positions - youtube_positions):
            missing.append(manifest_songs[position])

        for position in sorted(youtube_positions - manifest_positions):
            extra.append(youtube_songs[position].title)

        if youtube_compilation is None:
            missing.append(manifest_compilation)
        elif youtube_compilation.title != manifest_compilation:
            missing.append(manifest_compilation)
            extra.append(youtube_compilation.title)

        return missing, extra

    @staticmethod
    def _format_mismatch_error(
        missing: list[str],
        extra: list[str],
    ) -> str:
        lines = ["Album videos do not match between manifest and YouTube."]

        if missing:
            lines.append("Missing from YouTube:")
            lines.extend(f"  {title}" for title in missing)

        if extra:
            lines.append("Extra on YouTube:")
            lines.extend(f"  {title}" for title in extra)

        return "\n".join(lines)

    def _build_videos(
        self,
        manifest: AlbumManifest,
        manifest_songs: dict[int, str],
        youtube_songs: dict[int, YouTubeVideo],
        youtube_compilation: YouTubeVideo,
    ) -> list[Video]:
        videos: list[Video] = []

        for position in sorted(manifest_songs):
            youtube_video = youtube_songs[position]
            manifest_title = manifest_songs[position]

            metadata = self._build_song_metadata(
                manifest=manifest,
                manifest_title=manifest_title,
                position=position,
            )

            videos.append(
                Video(
                    video_id=youtube_video.video_id,
                    position=position,
                    video_type=VideoType.SONG,
                    metadata=metadata,
                )
            )

        compilation_position = len(manifest.videos)

        metadata = self._build_compilation_metadata(
            manifest=manifest,
            youtube_video=youtube_compilation,
            position=compilation_position,
        )

        videos.append(
            Video(
                video_id=youtube_compilation.video_id,
                position=compilation_position,
                video_type=VideoType.COMPILATION,
                metadata=metadata,
            )
        )

        return videos

    def _build_song_metadata(
        self,
        manifest: AlbumManifest,
        manifest_title: str,
        position: int,
    ) -> VideoMetadata:
        song_title = self._remove_position_prefix(manifest_title)

        desired_title = self._build_song_title(
            name_prefix=manifest.name_prefix,
            song_title=song_title,
        )

        publish_at = self._calculate_publish_at(
            manifest=manifest,
            position=position,
        )

        return VideoMetadata(
            title=desired_title,
            description=manifest.description,
            tags=list(manifest.tags) if manifest.tags is not None else None,
            playlists=list(manifest.playlists),
            game=manifest.game,
            made_for_kids=manifest.made_for_kids,
            contains_synthetic_media=manifest.contains_synthetic_media,
            publish_at=publish_at,
            thumbnail=manifest.thumbnail,
        )

    def _build_compilation_metadata(
        self,
        manifest: AlbumManifest,
        youtube_video: YouTubeVideo,
        position: int,
    ) -> VideoMetadata:
        current_description = youtube_video.description or ""

        combined_description = (
            f"{current_description}\n\n{manifest.description}"
        )

        if len(combined_description) > 5000:
            desired_description = current_description
        else:
            desired_description = combined_description

        publish_at = self._calculate_publish_at(
            manifest=manifest,
            position=position,
        )

        return VideoMetadata(
            title=youtube_video.title,
            description=desired_description,
            tags=list(manifest.tags) if manifest.tags is not None else None,
            playlists=list(manifest.playlists),
            game=manifest.game,
            made_for_kids=manifest.made_for_kids,
            contains_synthetic_media=manifest.contains_synthetic_media,
            publish_at=publish_at,
            thumbnail=manifest.thumbnail,
        )

    @classmethod
    def _build_song_title(
        cls,
        name_prefix: str,
        song_title: str,
    ) -> str:
        title = f"{name_prefix}: {song_title}"

        while len(title) > 100:
            last_space = title.rfind(" ")

            if last_space == -1:
                return title[:100]

            title = title[:last_space]

        return title

    @classmethod
    def _remove_position_prefix(cls, title: str) -> str:
        match = cls._SONG_TITLE_PATTERN.match(title)

        if match is None:
            raise AlbumBuildError(
                f"Song title does not contain a valid position: {title!r}."
            )

        return match.group(2)

    @staticmethod
    def _calculate_publish_at(
        manifest: AlbumManifest,
        position: int,
    ) -> datetime:
        publication = manifest.publication

        return publication.first_publish_at + timedelta(
            days=(position - 1) * publication.interval_days
        )

from __future__ import annotations

from datetime import datetime
from typing import Any


class AlbumManifestValidator:
    """Validates the structure and types of an album manifest."""

    REQUIRED_KEYS = {
        "album",
        "name_prefix",
        "videos",
        "description",
        "thumbnail",
        "playlists",
        "made_for_kids",
        "contains_synthetic_media",
        "tags",
        "game",
        "publication",
    }

    PUBLICATION_REQUIRED_KEYS = {
        "first_publish_at",
        "interval_days",
    }

    def validate(self, data: Any) -> list[str]:
        """
        Validate the manifest structure.

        Returns:
            A list containing every structural or type error found.
        """

        errors: list[str] = []

        if not isinstance(data, dict):
            return ["Manifest root must be a mapping."]

        errors.extend(self._validate_required_keys(data))
        errors.extend(self._validate_fields(data))

        publication = data.get("publication")

        if isinstance(publication, dict):
            errors.extend(
                self._validate_publication(publication)
            )

        return errors

    def _validate_required_keys(
        self,
        data: dict[str, Any],
    ) -> list[str]:
        return [
            f"Missing required key: '{key}'."
            for key in sorted(self.REQUIRED_KEYS - data.keys())
        ]

    def _validate_fields(
        self,
        data: dict[str, Any],
    ) -> list[str]:
        errors: list[str] = []

        for field in (
            "album",
            "name_prefix",
            "description",
            "game",
        ):
            if field in data and not isinstance(data[field], str):
                errors.append(
                    f"'{field}' must be a string."
                )

        if "videos" in data:
            errors.extend(
                self._validate_string_list(
                    data["videos"],
                    "videos",
                )
            )

        if "playlists" in data:
            errors.extend(
                self._validate_string_list(
                    data["playlists"],
                    "playlists",
                )
            )

        if "tags" in data:
            tags = data["tags"]

            if tags is not None:
                errors.extend(
                    self._validate_string_list(
                        tags,
                        "tags",
                    )
                )

        if "thumbnail" in data:
            if (
                data["thumbnail"] is not None
                and not isinstance(data["thumbnail"], str)
            ):
                errors.append(
                    "'thumbnail' must be a string or null."
                )

        if "made_for_kids" in data:
            if not isinstance(data["made_for_kids"], bool):
                errors.append(
                    "'made_for_kids' must be a boolean."
                )

        if "contains_synthetic_media" in data:
            if not isinstance(
                data["contains_synthetic_media"],
                bool,
            ):
                errors.append(
                    "'contains_synthetic_media' must be a boolean."
                )

        if "publication" in data:
            if not isinstance(data["publication"], dict):
                errors.append(
                    "'publication' must be a mapping."
                )

        return errors

    def _validate_publication(
        self,
        publication: dict[str, Any],
    ) -> list[str]:
        errors: list[str] = []

        errors.extend(
            f"Missing required key: 'publication.{key}'."
            for key in sorted(
                self.PUBLICATION_REQUIRED_KEYS
                - publication.keys()
            )
        )

        if "first_publish_at" in publication:
            value = publication["first_publish_at"]

            if not isinstance(value, str):
                errors.append(
                    "'publication.first_publish_at' "
                    "must be a string."
                )
            else:
                try:
                    datetime.fromisoformat(value)
                except ValueError:
                    errors.append(
                        "'publication.first_publish_at' "
                        "must be a valid ISO 8601 datetime."
                    )

        if "interval_days" in publication:
            value = publication["interval_days"]

            if isinstance(value, bool) or not isinstance(value, int):
                errors.append(
                    "'publication.interval_days' "
                    "must be an integer."
                )

        return errors

    @staticmethod
    def _validate_string_list(
        value: Any,
        field: str,
    ) -> list[str]:
        errors: list[str] = []

        if not isinstance(value, list):
            return [f"'{field}' must be a list."]

        for index, item in enumerate(value):
            if not isinstance(item, str):
                errors.append(
                    f"'{field}[{index}]' must be a string."
                )

        return errors

class ManifestError(Exception):
    """Base exception for manifest loading errors."""


class ManifestParseError(ManifestError):
    """Raised when the YAML cannot be parsed."""


class ManifestConfigurationError(ManifestError):
    """Raised when the manifest structure is invalid."""

from pathlib import Path
from typing import Any

import yaml

from services.youtube.album_manifest.exceptions import (
    ManifestError,
    ManifestParseError,
)

class YamlParser:
    @staticmethod
    def parse(path: Path) -> Any:
        """Parse the YAML document."""

        try:
            with path.open(
                "r",
                encoding="utf-8",
            ) as file:
                return yaml.safe_load(file)

        except yaml.YAMLError as exc:
            problem = getattr(
                exc,
                "problem",
                None,
            )
            mark = getattr(
                exc,
                "problem_mark",
                None,
            )

            if mark is not None:
                location = (
                    f"line {mark.line + 1}, "
                    f"column {mark.column + 1}"
                )
            else:
                location = "unknown location"

            detail = problem or str(exc)

            raise ManifestParseError(
                f"Invalid YAML at {location}: {detail}"
            ) from exc

        except OSError as exc:
            raise ManifestError(
                f"Unable to read manifest '{path}': {exc}"
            ) from exc

from __future__ import annotations

from pathlib import Path

from domain.youtube.album_manifest import AlbumManifest

from services.youtube.album_manifest.album_manifest_validator import (
    AlbumManifestValidator,
)
from services.youtube.album_manifest.exceptions import (
    ManifestConfigurationError,
)
from services.youtube.album_manifest.yaml_parser import YamlParser
from services.youtube.album_manifest.yaml_mapper import YamlMapper


class YamlReader:
    """Orchestrates the YAML album manifest reading pipeline."""

    def __init__(self) -> None:
        self._parser = YamlParser()
        self._validator = AlbumManifestValidator()
        self._mapper = YamlMapper()

    def read(self, path: Path) -> AlbumManifest:
        """Read a YAML file and return an AlbumManifest."""

        data = self._parser.parse(path)
        errors = self._validator.validate(data)

        if errors:
            raise ManifestConfigurationError(
                "Invalid manifest configuration:\n"
                + "\n".join(
                    f"- {error}"
                    for error in errors
                )
            )

        return self._mapper.map(data)

from __future__ import annotations

from pathlib import Path

from google.auth.transport.requests import Request
from google.oauth2.credentials import Credentials
from google_auth_oauthlib.flow import InstalledAppFlow
from googleapiclient.discovery import Resource, build


class YouTubeClient:
    """Provide authenticated and encapsulated access to the YouTube Data API."""

    SCOPES = [
        "https://www.googleapis.com/auth/youtube",
    ]

    def __init__(
        self,
        client_secrets_path: Path,
        token_path: Path,
    ) -> None:
        self._client_secrets_path = client_secrets_path
        self._token_path = token_path
        self._service = self._authenticate()

    @property
    def service(self) -> Resource:
        """Return the authenticated YouTube API service."""
        return self._service

    def _authenticate(self) -> Resource:
        """Authenticate the user and create the YouTube API service."""
        credentials = self._load_credentials()

        if credentials is None or not credentials.valid:
            credentials = self._refresh_or_authorize(credentials)

        self._save_credentials(credentials)

        return build(
            "youtube",
            "v3",
            credentials=credentials,
        )

    def _load_credentials(self) -> Credentials | None:
        """Load previously stored OAuth credentials."""
        if not self._token_path.exists():
            return None

        return Credentials.from_authorized_user_file(
            str(self._token_path),
            self.SCOPES,
        )

    def _refresh_or_authorize(
        self,
        credentials: Credentials | None,
    ) -> Credentials:
        """Refresh existing credentials or perform OAuth authorization."""
        if credentials is not None and credentials.expired:
            if credentials.refresh_token is None:
                raise RuntimeError(
                    "Stored YouTube credentials have expired and "
                    "contain no refresh token."
                )

            credentials.refresh(Request())
            return credentials

        flow = InstalledAppFlow.from_client_secrets_file(
            str(self._client_secrets_path),
            self.SCOPES,
        )

        return flow.run_local_server(port=0)

    def _save_credentials(self, credentials: Credentials) -> None:
        """Persist OAuth credentials locally."""
        self._token_path.parent.mkdir(
            parents=True,
            exist_ok=True,
        )

        self._token_path.write_text(
            credentials.to_json(),
            encoding="utf-8",
        )

from __future__ import annotations

from pathlib import Path
from typing import Any

from googleapiclient.errors import HttpError
from googleapiclient.http import MediaFileUpload
from rich.console import Console

from services.youtube.api.client import YouTubeClient


class YouTubeApiError(RuntimeError):
    """Raised when the YouTube Data API returns an error."""


class YouTubeQuotaExceededError(YouTubeApiError):
    """Raised when YouTube rejects a request because the quota is exhausted."""


class YouTubeMethods:
    """Provide concrete operations against the YouTube Data API."""

    def __init__(self, client: YouTubeClient) -> None:
        self._service = client.service
        self._console = Console()

    def channels_list(
        self,
        *,
        part: str = "contentDetails",
        mine: bool = True,
    ) -> dict[str, Any]:
        """Retrieve channel information for the authenticated user."""
        return self._execute(
            "channels.list",
            self._service.channels().list(
                part=part,
                mine=mine,
            ),
        )

    def playlist_items_list(
        self,
        *,
        playlist_id: str,
        part: str = "snippet,contentDetails,status",
        max_results: int = 50,
        page_token: str | None = None,
    ) -> dict[str, Any]:
        """Retrieve a page of items from a YouTube playlist."""
        request_kwargs: dict[str, Any] = {
            "part": part,
            "playlistId": playlist_id,
            "maxResults": max_results,
        }

        if page_token is not None:
            request_kwargs["pageToken"] = page_token

        return self._execute(
            "playlistItems.list",
            self._service.playlistItems().list(**request_kwargs),
        )

    def videos_list(
        self,
        *,
        video_ids: list[str],
        part: str = "snippet,status",
    ) -> dict[str, Any]:
        """Retrieve information for one or more YouTube videos."""
        if not video_ids:
            raise ValueError("video_ids must not be empty.")

        return self._execute(
            "videos.list",
            self._service.videos().list(
                part=part,
                id=",".join(video_ids),
            ),
        )

    def videos_update(
        self,
        *,
        video_resource: dict[str, Any],
        part: str = "snippet,status",
    ) -> dict[str, Any]:
        """Update a YouTube video."""
        return self._execute(
            "videos.update",
            self._service.videos().update(
                part=part,
                body=video_resource,
            ),
        )

    def thumbnails_set(
        self,
        *,
        video_id: str,
        thumbnail_path: Path,
    ) -> dict[str, Any]:
        """Set a video's custom thumbnail."""
        if not thumbnail_path.is_file():
            raise FileNotFoundError(
                f"Thumbnail file does not exist: {thumbnail_path}"
            )

        media = MediaFileUpload(
            str(thumbnail_path),
            mimetype="image/jpeg",
        )

        return self._execute(
            "thumbnails.set",
            self._service.thumbnails().set(
                videoId=video_id,
                media_body=media,
            ),
        )

    def playlists_list(
        self,
        *,
        part: str = "snippet,contentDetails",
        mine: bool = True,
        max_results: int = 50,
        page_token: str | None = None,
    ) -> dict[str, Any]:
        """Retrieve a page of playlists for the authenticated user."""
        request_kwargs: dict[str, Any] = {
            "part": part,
            "mine": mine,
            "maxResults": max_results,
        }

        if page_token is not None:
            request_kwargs["pageToken"] = page_token

        return self._execute(
            "playlists.list",
            self._service.playlists().list(**request_kwargs),
        )

    def playlist_items_insert(
        self,
        *,
        playlist_item_resource: dict[str, Any],
        part: str = "snippet",
    ) -> dict[str, Any]:
        """Add a video to a YouTube playlist."""
        return self._execute(
            "playlistItems.insert",
            self._service.playlistItems().insert(
                part=part,
                body=playlist_item_resource,
            ),
        )

    def _execute(
        self,
        operation: str,
        request: Any,
    ) -> dict[str, Any]:
        """Execute an API request and translate Google API errors."""
        try:
            response = request.execute()
        except HttpError as error:
            if self._is_quota_exceeded(error):
                self._console.print(
                    f"[red][YouTube API][/red] "
                    f"[bold]{operation}[/bold] → quotaExceeded"
                )
                raise YouTubeQuotaExceededError(
                    "YouTube API quota has been exceeded."
                ) from error

            self._console.print(
                f"[red][YouTube API][/red] "
                f"[bold]{operation}[/bold] → HTTP {error.resp.status}"
            )
            raise YouTubeApiError(
                f"YouTube API request failed for {operation}: {error}"
            ) from error

        self._console.print(
            f"[green][YouTube API][/green] "
            f"[bold]{operation}[/bold] → OK"
        )
        return response

    @staticmethod
    def _is_quota_exceeded(error: HttpError) -> bool:
        """Return whether an API error represents exhausted quota."""
        content = error.content

        if isinstance(content, bytes):
            content = content.decode("utf-8", errors="replace")

        return "quotaExceeded" in str(content)

from __future__ import annotations

from typing import Any

from domain.youtube.youtube_video import PrivacyStatus, YouTubeVideo
from services.youtube.api.methods import YouTubeMethods


class YouTubeDiscovery:
    """Discover the current album videos uploaded to YouTube."""

    def __init__(self, methods: YouTubeMethods) -> None:
        self._methods = methods

    def discover(self) -> tuple[YouTubeVideo, ...]:
        """Discover the first continuous sequence of private videos."""

        uploads_playlist_id = self._get_uploads_playlist_id()

        videos: list[YouTubeVideo] = []
        found_private_block = False
        page_token: str | None = None

        while True:
            response = self._methods.playlist_items_list(
                playlist_id=uploads_playlist_id,
                page_token=page_token,
            )

            for item in response.get("items", []):
                video = self._map_video(item)

                if video.privacy_status is PrivacyStatus.PRIVATE:
                    found_private_block = True
                    videos.append(video)
                    continue

                if found_private_block:
                    return tuple(videos)

            page_token = response.get("nextPageToken")

            if page_token is None:
                return tuple(videos)

    def _get_uploads_playlist_id(self) -> str:
        """Return the authenticated user's uploads playlist ID."""

        response = self._methods.channels_list()

        items = response.get("items", [])

        if not items:
            raise RuntimeError("Authenticated YouTube channel was not found.")

        playlist_id = (
            items[0]
            .get("contentDetails", {})
            .get("relatedPlaylists", {})
            .get("uploads")
        )

        if not playlist_id:
            raise RuntimeError("YouTube uploads playlist was not found.")

        return playlist_id

    @staticmethod
    def _map_video(item: dict[str, Any]) -> YouTubeVideo:
        """Create a YouTubeVideo from a playlist item."""

        content_details = item.get("contentDetails", {})
        snippet = item.get("snippet", {})
        status = item.get("status", {})

        return YouTubeVideo(
            video_id=content_details["videoId"],
            title=snippet["title"],
            description=snippet.get("description"),
            privacy_status=PrivacyStatus(status["privacyStatus"]),
        )
